565	// PUT /coaches/me — update own coach profile (coach role required)
566	// Must be declared *before* PUT /coaches/:id, otherwise the `:id` pattern
567	// swallows "me" and the parseInt there rejects it with "Invalid id".
568	router.put("/coaches/me", requireAuth, async (req, res): Promise<void> => {
569	  const userId = getCurrentUserId(req)!;
570	
571	  const callerRole = await getUserRole(userId);
572	  if (callerRole !== "coach" && callerRole !== "admin") {
573	    res.status(403).json({ error: "Forbidden – coach role required" });
574	    return;
575	  }
576	
577	  const parsed = CoachUpsertBody.safeParse(req.body);
578	  if (!parsed.success) {
579	    res.status(400).json({ error: "Invalid body", details: parsed.error.flatten() });
580	    return;
581	  }
582	  const {
583	    name, email, bio, photoUrl, videoUrl, sports, sportsAudiences,
584	    availabilityDescription, phone, isAcceptingStudents, experienceYears,
585	    qualifications,
586	    travelPolicy, courtPaymentModel, cancellationPolicy,
587	  } = parsed.data;
588	
589	  const finalSports = sportsAudiences
590	    ? sportsAudiences.map((e) => e.sport)
591	    : (sports ?? []);
592	
593	  const [existing] = await db.select().from(coachesTable).where(eq(coachesTable.userId, userId));
594	
595	  if (existing) {
596	    // pricePerHour is intentionally omitted — it's owned by
597	    // syncCoachStartingPrice in lib/coach-pricing.ts and must never be set
598	    // from a profile-edit body.
599	    const [updated] = await db.update(coachesTable).set({
600	      name, email,
601	      bio: bio ?? null,
602	      photoUrl: photoUrl ?? null,
603	      videoUrl: videoUrl ?? null,
604	      sports: finalSports,
605	      availabilityDescription: availabilityDescription ?? null,
606	      phone: phone ?? null,
607	      ...(isAcceptingStudents !== undefined && { isAcceptingStudents }),
608	      experienceYears: experienceYears ?? null,
609	      ...(qualifications !== undefined && { qualifications }),
610	      ...(travelPolicy !== undefined && { travelPolicy }),
611	      ...(courtPaymentModel !== undefined && { courtPaymentModel }),
612	      ...(cancellationPolicy !== undefined && { cancellationPolicy }),
613	    }).where(eq(coachesTable.userId, userId)).returning();
614	    if (sportsAudiences) await syncCoachSports(updated.id, sportsAudiences);
