639	// PUT /coaches/:id — update coach profile (own profile or admin)
640	router.put("/coaches/:id", requireAuth, async (req, res): Promise<void> => {
641	  const id = parseInt(String(req.params.id), 10);
642	  if (isNaN(id)) { res.status(400).json({ error: "Invalid id" }); return; }
643	
644	  const userId = getCurrentUserId(req)!;
645	  const [coach] = await db.select().from(coachesTable).where(eq(coachesTable.id, id));
646	  if (!coach) { res.status(404).json({ error: "Coach not found" }); return; }
647	
648	  const canEdit = await isOwner(req, coach.userId);
649	  if (!canEdit && coach.userId !== userId) {
650	    res.status(403).json({ error: "Forbidden" });
651	    return;
652	  }
653	
654	  const parsed = CoachUpsertBody.partial().safeParse(req.body);
655	  if (!parsed.success) {
656	    res.status(400).json({ error: "Invalid body", details: parsed.error.flatten() });
657	    return;
658	  }
659	  const {
660	    name, email, bio, photoUrl, videoUrl, sports, sportsAudiences,
661	    availabilityDescription, phone, isAcceptingStudents, experienceYears,
662	    qualifications,
663	    travelPolicy, courtPaymentModel, cancellationPolicy,
664	  } = parsed.data;
665	
666	  // If the partial body supplies sportsAudiences, derive `sports` from it so
667	  // the two stay aligned even on partial updates. If only `sports` is given,
668	  // honor it directly (legacy clients).
669	  const sportsUpdate = sportsAudiences
670	    ? { sports: sportsAudiences.map((e) => e.sport) }
671	    : (sports !== undefined ? { sports } : {});
672	
673	  // pricePerHour is intentionally omitted — owned by syncCoachStartingPrice.
674	  const [updated] = await db.update(coachesTable).set({
675	    ...(name !== undefined && { name }),
676	    ...(email !== undefined && { email }),
677	    bio: bio ?? null,
678	    photoUrl: photoUrl ?? null,
679	    videoUrl: videoUrl ?? null,
680	    ...sportsUpdate,
681	    availabilityDescription: availabilityDescription ?? null,
682	    phone: phone ?? null,
683	    ...(isAcceptingStudents !== undefined && { isAcceptingStudents }),
684	    experienceYears: experienceYears ?? null,
685	    ...(qualifications !== undefined && { qualifications }),
686	    ...(travelPolicy !== undefined && { travelPolicy }),
687	    ...(courtPaymentModel !== undefined && { courtPaymentModel }),
688	    ...(cancellationPolicy !== undefined && { cancellationPolicy }),
689	  }).where(eq(coachesTable.id, id)).returning();
690	
691	  if (sportsAudiences) await syncCoachSports(updated.id, sportsAudiences);
692	
693	  const sa = await loadSportsAudiences([updated.id]);
694	  res.json({ ...formatCoach(updated), sportsAudiences: sa.get(updated.id) ?? [] });
695	});
